const ctx = $('Build Elevator Context').first().json;
const ai = $('Triage Elevator Issue Agent').first().json.output;
const techs = $input.all().map(i => i.json).filter(t => t.technician_id);
const rank = s => Number(String(s || '').match(/\d/)?.[0] || 1);
const need = rank(ai.required_skill);
const sevMap = { P1: 'P1 - Critical/Passenger Trapped', P2: 'P2 - Lift Down', P3: 'P3 - Noise/Degraded' };
const slaHours = { P1: 1, P2: 4, P3: 24 };
const zone = ctx.elevator.zone_territory; // optional column on Elevators
const inZone = t => !zone || String(t.zone_territory).toLowerCase() === String(zone).toLowerCase();
const load = t => Number(t.active_tickets_count || 0);
const sortFn = (a, b) => load(a) - load(b) || rank(a.skill_level) - rank(b.skill_level);
const skilled = techs.filter(t => rank(t.skill_level) >= need);

let pool = skilled.filter(t => t.status === 'Available' && inZone(t));
if (!pool.length) pool = skilled.filter(t => t.status === 'Available');
if (!pool.length && ai.severity === 'P1') pool = techs.filter(t => t.status !== 'Off Duty' && rank(t.skill_level) >= need);
if (!pool.length && ai.severity === 'P1') pool = techs.filter(t => t.status !== 'Off Duty');
const tech = pool.sort(sortFn)[0] || null;

const now = new Date();
const sla = new Date(now.getTime() + slaHours[ai.severity] * 3600e3);
const ticket_id = 'TICK-' + Date.now();
const e = ctx.elevator;
const hist = ctx.history.map(h => `- ${String(h.submitted_at).slice(0,10)}: ${h.ai_root_cause || h.work_performed || ''}`).join('\n') || '- No prior records';

const dispatch_message =
`🚨 ${sevMap[ai.severity]} | ${ticket_id}
Building: ${e.building_name}
Address: ${e.building_address}
Contact: ${e.building_contact_name} (${e.building_contact_phone})
Unit: ${e.elevator_id} - ${e.make_model}
Fault: ${ai.summary}
Complaint: ${ctx.complaint_text}
SLA deadline: ${sla.toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'})}
Recent history:
${hist}

Reply with your field notes when done (ticket ${ticket_id}).`;

const client_email_body =
`Hello ${e.building_contact_name},

We've received your complaint for ${e.elevator_id} (${e.building_name}) and logged it as ticket ${ticket_id}.

Priority: ${sevMap[ai.severity]}
Issue: ${ai.summary}
${tech ? 'Assigned technician: ' + tech.name + ' (' + tech.phone + ')' : 'A technician is being assigned and our dispatcher will call you shortly.'}
Target response by: ${sla.toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'})}

Reference: ${ticket_id}`;

return [{ json: {
  ticket_id, elevator_id: ctx.elevator_id, created_at: now.toISOString(),
  complaint_raw_text: ctx.complaint_text, severity: sevMap[ai.severity], severity_code: ai.severity,
  assigned_technician_id: tech ? tech.technician_id : '',
  ticket_status: tech ? 'In Progress' : 'Open',
  sla_deadline: sla.toISOString(),
  elevator_new_status: ai.severity === 'P3' ? 'Degraded' : 'Under Maintenance',
  technician_id: tech ? tech.technician_id : '',
  tech_name: tech ? tech.name : '', tech_phone: tech ? String(tech.phone).replace(/\D/g, '') : '',
  tech_active_count: tech ? load(tech) : 0,
  building_contact_email: e.building_contact_email,
  ai_summary: ai.summary, dispatch_message, client_email_body
}}];

