parameters.jsCode:
const ctx = $('Build Parts Context').first().json;
const ai = $('Extract Report Data Agent').first().json.output;
const now = new Date();
const days = ai.safety_concern ? Math.min(Number(ai.next_service_days) || 30, 14) : (Number(ai.next_service_days) || 30);
const next = new Date(now.getTime() + days * 864e5).toISOString().slice(0, 10);
const complete = ai.work_complete !== false;
const used = ai.parts_used || [];
const future = ai.parts_required_future || [];
const label = p => (p.part_sku || p.part_name || 'unknown');
const parts_replaced = used.map(p => `${label(p)} x${p.quantity || 1}`).join(', ');
const next_recommended_action = [
  ai.next_recommended_action,
  future.length ? 'Order: ' + future.map(p => `${label(p)}${p.needed_within_days ? ' (within ' + p.needed_within_days + 'd)' : ''}`).join(', ') : ''
].filter(Boolean).join(' | ');
const e = ctx.elevator;
const html = `<p>Hello ${e.building_contact_name},</p>
<p>Service update for <b>${e.building_name}</b> - unit <b>${ctx.elevator_id}</b> (ticket ${ctx.ticket_id}).</p>
<p><b>Status:</b> ${complete ? 'Lift restored and operational' : 'Work in progress - awaiting parts / follow-up visit'}</p>
<p><b>What was done:</b> ${ai.client_friendly_summary}</p>
<p><b>Machine health rating:</b> ${ai.machine_health_score}/10${ai.safety_concern ? ' (follow-up recommended for safety-related wear)' : ''}</p>
<p><b>Next scheduled visit:</b> ${next}</p>`;
return [{ json: {
  log_id: 'LOG-' + Date.now(), ticket_id: ctx.ticket_id, elevator_id: ctx.elevator_id,
  technician_id: ctx.technician_id, submitted_at: now.toISOString(),
  raw_technician_notes: ctx.notes, ai_root_cause: ai.root_cause, work_performed: ai.work_performed,
  parts_replaced, machine_health_score: ai.machine_health_score, next_recommended_action,
  next_scheduled_maintenance: next, last_service_date: now.toISOString().slice(0, 10),
  elevator_status: complete ? 'Active' : 'Degraded',
  ticket_status: complete ? 'Closed' : 'Pending Parts',
  closure_summary: ai.client_friendly_summary,
  building_contact_email: e.building_contact_email, building_name: e.building_name,
  parts_used: used, client_email_html: html
}}];

const p = $('Format Service Log Entry').first().json;
const ctx = $('Build Parts Context').first().json;
const out = [];
for (const u of (p.parts_used || [])) {
  const cat = ctx.parts_catalog.find(c => c.part_sku === u.part_sku);
  if (!cat) continue;
  const newQty = Math.max(0, cat.stock_quantity - Number(u.quantity || 1));
  out.push({ json: { part_sku: cat.part_sku, part_name: cat.part_name, new_stock: newQty,
    reorder_threshold: cat.reorder_threshold, low_stock: newQty <= cat.reorder_threshold } });
}
return out;

const body = $('When Tech Report Received').first().json.body;
const ticket = $('Read Ticket in Sheets').first().json;
if (!ticket.ticket_id) throw new Error('Unknown ticket_id: ' + body.ticket_id);
const elevator = $('Read Elevator Specs in Sheets').first().json;
const parts = $('Read Parts in Sheets').all().map(i => i.json).filter(p => p.part_sku);
return [{ json: {
  ticket_id: ticket.ticket_id,
  elevator_id: ticket.elevator_id,
  technician_id: body.technician_id || ticket.assigned_technician_id,
  notes: body.notes,
  elevator,
  parts_catalog: parts.map(p => ({ part_sku: p.part_sku, part_name: p.part_name, category: p.category,
    stock_quantity: Number(p.stock_quantity || 0), reorder_threshold: Number(p.reorder_threshold || 0) }))
}}];

